// Do not edit this file.

package networkdelay

import "testing"

func check(t *testing.T, times [][]int, n, k, want int) {
	t.Helper()
	if got := NetworkDelayTime(times, n, k); got != want {
		t.Fatalf("NetworkDelayTime(%v, %d, %d) = %d, want %d", times, n, k, got, want)
	}
}

func TestClassic(t *testing.T) {
	check(t, [][]int{{2, 1, 1}, {2, 3, 1}, {3, 4, 1}}, 4, 2, 2)
}

func TestSingleEdge(t *testing.T) {
	check(t, [][]int{{1, 2, 1}}, 2, 1, 1)
}

// edges are directed: 2 can't reach 1
func TestUnreachable(t *testing.T) {
	check(t, [][]int{{1, 2, 1}}, 2, 2, -1)
}

func TestSingleNode(t *testing.T) {
	check(t, [][]int{}, 1, 1, 0)
}

func TestIsolatedNode(t *testing.T) {
	check(t, [][]int{{1, 2, 1}}, 3, 1, -1)
}

// direct 1->3 costs 10, but 1->2->3 costs 2
func TestIndirectPathIsShorter(t *testing.T) {
	check(t, [][]int{{1, 3, 10}, {1, 2, 1}, {2, 3, 1}}, 3, 1, 2)
}

// BFS by hop count would settle 4 via 1->4 (9); Dijkstra finds 1->2->3->4 (3)
func TestFewestHopsNotShortest(t *testing.T) {
	check(t, [][]int{{1, 4, 9}, {1, 2, 1}, {2, 3, 1}, {3, 4, 1}}, 4, 1, 3)
}

func TestZeroWeightEdges(t *testing.T) {
	check(t, [][]int{{1, 2, 0}, {2, 3, 0}}, 3, 1, 0)
}

func TestCycle(t *testing.T) {
	check(t, [][]int{{1, 2, 1}, {2, 3, 2}, {3, 1, 4}}, 3, 1, 3)
}
